from __future__ import annotations
from dataclasses import dataclass
from hashlib import sha256
import json,shutil
from pathlib import Path
from m2_helpers import UUIDSequence,fixed_now
from qbcore.cli import run_inventory
from qbcore.parse_service import run_single_choice_parse

FIXTURES=Path(__file__).parent/'fixtures/m3-answer-association'
@dataclass
class M3Workspace:
    input_root:Path;workspace_root:Path;question_source_id:str;answer_source_id:str;candidate_hash:str

def file_hash(path):return sha256(path.read_bytes()).hexdigest()
def bootstrap(root:Path,*,answer='answers-confirmable.txt',questions='questions-strict-two.md')->M3Workspace:
    inp=root/'input';ws=root/'workspace';inp.mkdir(parents=True)
    shutil.copy2(FIXTURES/questions,inp/'questions.md');shutil.copy2(FIXTURES/answer,inp/'answers.txt')
    run_inventory(input_root=inp,workspace_root=ws,now=fixed_now,uuid_factory=UUIDSequence(100))
    reg=json.loads((ws/'registry/sources.json').read_text(encoding='utf-8'))
    q=next(x for x in reg['sources'] if x['current_relative_path']=='questions.md');a=next(x for x in reg['sources'] if x['current_relative_path']=='answers.txt')
    run_single_choice_parse(input_root=inp,workspace_root=ws,source_id=q['source_id'],now=fixed_now,uuid_factory=UUIDSequence(1000))
    cp=ws/'candidates/sources'/f"{q['source_id']}.json"
    return M3Workspace(inp,ws,q['source_id'],a['source_id'],file_hash(cp))
def current_hash(case):
    p=case.workspace_root/'state/answer-association/current.json';return file_hash(p) if p.exists() else 'ABSENT'
def proposal_entry(result,conclusion,index=0):return [x for x in result['proposal']['entries'] if x['conclusion']==conclusion][index]
def rewrite_answer_and_inventory(case,text,*,uuid_start=20000):
    (case.input_root/'answers.txt').write_text(text,encoding='utf-8',newline='\n')
    run_inventory(input_root=case.input_root,workspace_root=case.workspace_root,now=fixed_now,uuid_factory=UUIDSequence(uuid_start))

